<?php if(($orderData['status'] ?? '')==='draft'): ?><div class="draft"><?php echo e(t('Provisional bill · payment pending','প্রাথমিক বিল · পেমেন্ট বাকি')); ?></div><?php elseif(($orderData['status'] ?? '')==='cancelled'): ?><div class="draft"><strong><?php echo e(t('Cancelled order','বাতিল অর্ডার')); ?></strong><br><?php echo e(t('No payment is due. Amounts below are the original quoted amounts.','কোনো টাকা পরিশোধ করতে হবে না। নিচের পরিমাণগুলো পূর্বের প্রস্তাবিত মূল্য।')); ?></div><?php endif; ?>
